import React, { useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";

function SuccessPage() {
  const location = useLocation();
  const navigate = useNavigate();

  const bookingData = location.state || {};
  const userId = localStorage.getItem("userId");   // Logged-in user
  const userEmail = localStorage.getItem("userEmail");

  useEffect(() => {
    if (!userId || !bookingData.slotNumber) return;

    // Prepare data for backend
    const dataToSend = {
      ...bookingData,
      email: userEmail
    };

    fetch(`http://localhost:8081/api/bookings?userId=${userId}&parkingSlotId=${bookingData.slotNumber}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(dataToSend)
    })
      .then(res => res.json())
      .then(data => console.log("✅ Booking saved & email sent:", data))
      .catch(err => console.error("❌ Error:", err));
  }, [bookingData, userId, userEmail]);

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <div style={styles.icon}>✅</div>
        <h1 style={styles.title}>Booking Successful!</h1>
        <p style={styles.subtitle}>Your parking slot has been confirmed.</p>
        <div style={styles.details}>
          {Object.entries(bookingData).map(([key, value]) => (
            <p key={key}><strong>{key}:</strong> {value}</p>
          ))}
        </div>
        <button style={styles.button} onClick={() => navigate("/home")}>Back to Home</button>
      </div>
    </div>
  );
}

const styles = {
  page: { display: "flex", justifyContent: "center", alignItems: "center", minHeight: "100vh", backgroundColor: "#f0f8f5", padding: "20px" },
  card: { backgroundColor: "#fff", padding: "30px", borderRadius: "12px", boxShadow: "0 4px 20px rgba(0,0,0,0.1)", textAlign: "center", maxWidth: "400px", width: "100%" },
  icon: { fontSize: "50px", marginBottom: "10px" },
  title: { fontSize: "24px", fontWeight: "bold", marginBottom: "5px" },
  subtitle: { fontSize: "16px", color: "#555", marginBottom: "20px" },
  details: { textAlign: "left", fontSize: "16px", marginBottom: "20px", backgroundColor: "#f9f9f9", padding: "15px", borderRadius: "8px" },
  button: { backgroundColor: "#28a745", color: "#fff", padding: "12px 25px", border: "none", borderRadius: "6px", fontSize: "16px", cursor: "pointer" }
};

export default SuccessPage;
